CREATE TABLE IF NOT EXISTS company_professional_link_events (id CHAR(36) PRIMARY KEY, company_id CHAR(36) NOT NULL, professional_user_id CHAR(36) NOT NULL, actor_user_id CHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_company_professional_link_events(company_id,professional_user_id,created_at), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(professional_user_id) REFERENCES users(id), FOREIGN KEY(actor_user_id) REFERENCES users(id));
